package com.motionlayer.render
import com.motionlayer.data.*
object KeyframeInterpolator {
 fun interpolateLayerAtTime(layer:Layer,timeMs:Long):Layer { val keys=layer.keyframes.sortedBy{it.timeMs}; if(keys.isEmpty()) return layer; val prev=keys.lastOrNull{it.timeMs<=timeMs} ?: keys.first(); val next=keys.firstOrNull{it.timeMs>=timeMs} ?: keys.last(); if(prev.id==next.id) return apply(layer,prev,1f); val raw=(timeMs-prev.timeMs).toFloat()/(next.timeMs-prev.timeMs).coerceAtLeast(1); val t=Easing.apply(next.easing,raw); fun v(a:Float,b:Float?)=a+((b ?: a)-a)*t; return layer.copy(x=v(prev.x?:layer.x,next.x), y=v(prev.y?:layer.y,next.y), scaleX=v(prev.scaleX?:layer.scaleX,next.scaleX), scaleY=v(prev.scaleY?:layer.scaleY,next.scaleY), rotationX=v(prev.rotationX?:layer.rotationX,next.rotationX), rotationY=v(prev.rotationY?:layer.rotationY,next.rotationY), rotationZ=v(prev.rotationZ?:layer.rotationZ,next.rotationZ), zDepth=v(prev.zDepth?:layer.zDepth,next.zDepth), opacity=v(prev.opacity?:layer.opacity,next.opacity), style=layer.style.copy(blur=v(prev.blur?:layer.style.blur,next.blur), shadowOpacity=v(prev.shadowOpacity?:layer.style.shadowOpacity,next.shadowOpacity)), mask=layer.mask.copy(maskX=v(prev.maskX?:layer.mask.maskX,next.maskX), maskY=v(prev.maskY?:layer.mask.maskY,next.maskY), maskWidth=v(prev.maskWidth?:layer.mask.maskWidth,next.maskWidth), maskHeight=v(prev.maskHeight?:layer.mask.maskHeight,next.maskHeight))) }
 private fun apply(l:Layer,k:Keyframe,t:Float)=l.copy(x=k.x?:l.x,y=k.y?:l.y,scaleX=k.scaleX?:l.scaleX,scaleY=k.scaleY?:l.scaleY,rotationX=k.rotationX?:l.rotationX,rotationY=k.rotationY?:l.rotationY,rotationZ=k.rotationZ?:l.rotationZ,zDepth=k.zDepth?:l.zDepth,opacity=k.opacity?:l.opacity)
}
